class Order:  # Aggregate Root
    def __init__(self, order_id: OrderId, allocation: int):
        self._id = order_id
        self._lines: list[OrderLine] = []
        self._allocation = allocation

    def add_line(self, product_id: ProductId, qty: Quantity) -> None:
        # All external code calls this — never OrderLine directly
        new_total = sum(l.quantity for l in self._lines) + qty.value
        if new_total > self._allocation:
            raise AllocationExceededError()
        self._lines.append(OrderLine(product_id, qty))

    @property
    def id(self) -> OrderId:
        return self._id  # Only the root's ID is externally addressable

# ACL translator — converts upstream FedEx model to downstream domain model
class FedExShippingAdapter:
    def __init__(self, fedex_client: FedExClient):
        self._client = fedex_client

    def track_shipment(self, shipment_id: ShipmentId) -> ShipmentStatus:
        # Downstream calls this — never FedEx types directly
        raw = self._client.track(tracking_number=shipment_id.value)
        return self._translate_status(raw["StatusDetail"]["Code"])

    def _translate_status(self, fedex_code: str) -> ShipmentStatus:
        mapping = {"DL": ShipmentStatus.DELIVERED, "IP": ShipmentStatus.IN_TRANSIT}
        return mapping.get(fedex_code, ShipmentStatus.UNKNOWN)

