# shared_kernel/money.py — co-owned by Orders and Billing contexts
from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP
from enum import Enum

class Currency(Enum):
    USD = "USD"
    EUR = "EUR"
    GBP = "GBP"

@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: Currency

    def __post_init__(self):
        if self.amount < Decimal("0"):
            raise ValueError("Money amount cannot be negative")

    def add(self, other: "Money") -> "Money":
        if self.currency != other.currency:
            raise CurrencyMismatchError()
        return Money(self.amount + other.amount, self.currency)

# Inventory context — consumer of OrderPlaced integration event
class OrderPlacedConsumer:
    def __init__(self, inventory_repo: InventoryRepository):
        self._repo = inventory_repo

    def handle(self, event: OrderPlacedIntegrationEvent) -> None:
        # Idempotency check: skip if already processed
        if self._repo.is_event_processed(event.event_id):
            return
        for line in event.lines:
            inventory = self._repo.find_by_product(ProductId(line.product_id))
            inventory.reserve(Quantity(line.quantity))  # own domain operation
            self._repo.save(inventory)
        self._repo.mark_event_processed(event.event_id)

