# Domain layer — defines what it needs (interface/port)
from abc import ABC, abstractmethod

class EmailSender(ABC):
    @abstractmethod
    def send(self, to: EmailAddress, subject: str, body: str) -> None: ...

# Infrastructure layer — provides how it is done (adapter)
class SendGridEmailSender(EmailSender):
    def __init__(self, api_key: str):
        self._client = SendGridAPIClient(api_key)

    def send(self, to: EmailAddress, subject: str, body: str) -> None:
        message = Mail(to_emails=to.value, subject=subject, plain_text_content=body)
        self._client.send(message)

# Manual optimistic locking in repository
class SqlInventoryRepository(InventoryRepository):
    def save(self, inventory: Inventory) -> None:
        rows_updated = self._db.execute(
            "UPDATE inventory SET quantity = ?, version = ? "
            "WHERE product_id = ? AND version = ?",
            (inventory.quantity, inventory.version + 1,
             inventory.product_id.value, inventory.version)
        )
        if rows_updated == 0:
            raise OptimisticLockException(
                f"Inventory for {inventory.product_id} was modified concurrently")

