# Downstream translator inside the Stripe ACL
class StripePaymentTranslator:
    def translate(self, stripe_payload: dict) -> PaymentResult:
        status_map = {
            "succeeded": PaymentStatus.CAPTURED,
            "requires_action": PaymentStatus.PENDING_AUTHENTICATION,
            "canceled": PaymentStatus.FAILED,
        }
        return PaymentResult(
            payment_id=PaymentId(stripe_payload["id"]),
            status=status_map.get(stripe_payload["status"], PaymentStatus.UNKNOWN),
            amount=Money(
                Decimal(str(stripe_payload["amount"])) / 100,
                Currency(stripe_payload["currency"].upper())
            )
        )

