# Composable specifications
class Specification:
    def is_satisfied_by(self, customer: Customer) -> bool:
        raise NotImplementedError
    def and_(self, other: "Specification") -> "Specification":
        return AndSpec(self, other)
    def or_(self, other: "Specification") -> "Specification":
        return OrSpec(self, other)
    def not_(self) -> "Specification":
        return NotSpec(self)

class ActiveCustomerSpec(Specification):
    def is_satisfied_by(self, c: Customer) -> bool:
        return c.is_active and not c.is_blacklisted

class PremiumTierSpec(Specification):
    def is_satisfied_by(self, c: Customer) -> bool:
        return c.tier == CustomerTier.PREMIUM

# Composition
eligible = ActiveCustomerSpec().and_(PremiumTierSpec())
targets = [c for c in customers if eligible.is_satisfied_by(c)]
